const runId = $execution.id;
const startTime = new Date().toISOString();
const workflowName = 'twitter-service';

return [{
  json: {
    runId,
    workflowName,
    startTime,
    recordsIn: 0,
    recordsOut: 0,
    errors: []
  }
}];

// Parse scraper output and normalize to common schema
const response = $input.item.json;
const tweets = [];

try {
  // Extract JSON from agent response
  let data = response;
  if (typeof response === 'string') {
    // Try to find JSON in the response
    const jsonMatch = response.match(/\[.*\]/s);
    if (jsonMatch) {
      data = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error('No JSON array found in response');
    }
  }

  // Normalize each tweet
  const dataArray = Array.isArray(data) ? data : [data];
  for (const tweet of dataArray) {
    const dateStr = new Date().toISOString().split('T')[0];
    tweets.push({
      platform: 'twitter',
      source_id: tweet.id || tweet.tweet_id || `twitter_${Date.now()}_${Math.random()}`,
      author: tweet.author || tweet.username || 'unknown',
      text: tweet.text || tweet.content || '',
      url: tweet.url || `https://twitter.com/i/status/${tweet.id}`,
      created_at: tweet.created_at || new Date().toISOString(),
      engagement_json: JSON.stringify({
        likes: parseInt(tweet.likes) || 0,
        retweets: parseInt(tweet.retweets) || 0,
        replies: parseInt(tweet.replies) || 0
      }),
      dedupe_key: `twitter_${tweet.id || Date.now()}_${dateStr}`
    });
  }
} catch (error) {
  console.error('Parse error:', error.message);
  return [{ json: { error: error.message, raw: response } }];
}

if (tweets.length === 0) {
  return [{ json: { error: 'No tweets parsed', raw: response } }];
}

return tweets.map(t => ({ json: t }));

