const enrichment = $input.item.json;
const original = $input.all()[0].json;

let sentiment = 'neutral';
let keywords = [];

try {
  // Try to parse JSON response from LLM
  const responseText = enrichment.response || enrichment.message || JSON.stringify(enrichment);
  const jsonMatch = responseText.match(/\{[^}]*\"sentiment\"[^}]*\}/s);

  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    sentiment = parsed.sentiment || 'neutral';
    keywords = parsed.keywords || [];
  } else {
    // Fallback: simple text analysis
    const text = responseText.toLowerCase();
    if (text.includes('positive')) sentiment = 'positive';
    else if (text.includes('negative')) sentiment = 'negative';

    // Extract words in quotes or after "keywords:"
    const keywordMatch = text.match(/keywords?:?\s*([^\n]+)/i);
    if (keywordMatch) {
      keywords = keywordMatch[1].split(',').map(k => k.trim().replace(/["'\[\]]/g, '')).slice(0, 5);
    }
  }
} catch (error) {
  console.error('Enrichment parse error:', error.message);
}

return [{
  json: {
    ...original,
    sentiment,
    keywords: JSON.stringify(keywords),
    trend_score: 0.0
  }
}];

