// Insert content via sqlite3 CLI
const { execSync } = require('child_process');
const d = $input.item.json;
const safe = (v) => String(v||'').replace(/'/g,"''");
const sql = `INSERT OR IGNORE INTO content_raw (platform, source_id, author, text, url, created_at, engagement_json, dedupe_key, captured_at) VALUES ('${safe(d.platform)}','${safe(d.source_id)}','${safe(d.author)}','${safe(d.text)}','${safe(d.url)}','${safe(d.created_at)}','${safe(JSON.stringify(d.engagement||{}))}','${safe(d.dedupe_key)}',datetime('now'))`;
try { execSync(`sqlite3 '/Users/redinside/.openclaw/workspace/data/social-monitoring.db' "${sql.replace(/"/g,'\"')}"`, {timeout:5000}); } catch(e) {}
return [{ json: { ...d, _inserted: 1 } }];

// Get last inserted content ID
const { execSync } = require('child_process');
try {
    const result = execSync(`sqlite3 '/Users/redinside/.openclaw/workspace/data/social-monitoring.db' "SELECT last_insert_rowid() as content_id"`, {encoding:'utf8',timeout:5000}).trim();
    const content_id = parseInt(result) || 0;
    return [{ json: { ...$input.item.json, content_id } }];
} catch(e) {
    return [{ json: { ...$input.item.json, content_id: 0 } }];
}

// Insert signals via sqlite3 CLI
const { execSync } = require('child_process');
const d = $input.item.json;
const safe = (v) => String(v||'').replace(/'/g,"''");
const sql = `INSERT OR IGNORE INTO content_signals (content_id, sentiment, keywords_json, trend_score, enriched_at) VALUES (${parseInt(d.content_id)||0},'${safe(d.sentiment)}','${safe(JSON.stringify(d.keywords||[]))}',${parseFloat(d.trend_score)||0},datetime('now'))`;
try { execSync(`sqlite3 '/Users/redinside/.openclaw/workspace/data/social-monitoring.db' "${sql.replace(/"/g,'\"')}"`, {timeout:5000}); } catch(e) {}
return [{ json: { ...d, _signals_inserted: 1 } }];

